select cellar.merge_product('3fa45792-61b0-402c-98a9-4cd30400a16b'::uuid, 'dc3aee34-2da3-4784-b7ee-c96b7f5ba4e4'::uuid, '2017');
update cellar.makers set website = coalesce(website, 'https://oregonspiritdistillers.com'), country = coalesce(country, 'US'), updated_at = now() where id = 'c17c3f51-4b58-40b0-ae57-f9ce459b7280';
